// Der Himmel als Hintergrundbild (Bild Nummer 2 aus der Sammlung „Background“)
Sprite himmel = new Sprite(400, 300, SpriteLibrary.Background, 2);
himmel.setAsBackgroundImage();

// Der Vogel startet links im Bild und singt zum Abflug
Vogel vogel = new Vogel(40, 300);
vogel.singen();

// Drei kleine Flügelschläge nach rechts – jedes Mal mit einem anderen Bild
vogel.flattern(1);
vogel.flattern(2);
vogel.flattern(0);

// Ein Vogel aus der Bildersammlung „Bird“.
// Die Sammlung hat drei Vogelbilder (Nummer 0, 1 und 2) mit verschiedenen Flügelstellungen.
// „Vogel extends Sprite“: Ein Vogel-Objekt IST EIN Sprite-Objekt (Grafik-Objekt).
class Vogel extends Sprite {

   Vogel(Integer x, Integer y) {
      // super(…) baut den Sprite-Teil des Vogels – das lernen wir in den nächsten Wochen.
      super(x, y, SpriteLibrary.Bird, 0);
      scale(5);   // Das Bild ist winzig: fünfmal so groß darstellen
   }

   // Ein kleiner Flügelschlag: 20 Pixel nach rechts,
   // dabei das Vogelbild mit der Nummer bild zeigen und kurz warten.
   void flattern(Integer bild) {
      move(20, 0);
      setImageIndex(bild);
      SystemTools.pause(60);
   }

   // Der Vogel singt sein Lied auf die Konsole.
   // Eigentlich sollte das Lied in EINER Zeile stehen …
   void singen() {
      println("Tschiep ");
      println("Tirili ");
      println("Tüüüt!");
   }

}
